def link_existing_appointments(apps, schema_editor):
    """Tie each existing appointment to the teacher account its name points at, when exactly one approved teacher has
    that name. An ambiguous or unknown name stays unlinked: nobody but a Master Admin sees it until it is fixed."""
    Appointment = apps.get_model("appointments", "Appointment")
    User = apps.get_model("accounts", "User")
    by_name = {}
    for user in User.objects.filter(role="TEACHER", approval_status="APPROVED"):
        by_name.setdefault(" ".join(f"{user.first_name} {user.last_name}".split()).casefold(), []).append(user)
